<?php
require __DIR__ . '/config.php'; require __DIR__ . '/database_upgrade.php';
try {$pdo=db();apply_database_upgrade($pdo);}catch(Throwable $e){http_response_code(503);exit('System database is unavailable. Please try again later.');}
if(!is_role('admin')){flash('Administrator access is required.','error');redirect('index.php?page=login');}
$view=$_GET['view']??'dashboard';
function admin_go(string $view):never{header('Location: admin.php?view='.$view);exit;}
function admin_head(string $title,string $content):never{$u=user();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | Davao Local Admin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="admin.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap" rel="stylesheet"></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">D</span>Davao <b>Local</b></a><p class="sidebar-label">ADMINISTRATION</p><a href="?view=dashboard">Dashboard</a><a href="?view=businesses">Businesses</a><a href="?view=pending">Pending verification</a><a href="?view=users">Users & owners</a><a href="?view=categories">Categories</a><a href="?view=reviews">Reviews</a><a href="?view=logs">Activity logs</a><a href="index.php?page=directory">View directory</a><a href="index.php?action=logout">Log out</a></aside><main class="admin-main"><header class="admin-top"><div><span class="eyebrow">DAVAO LOCAL ADMIN</span><h1><?=e($title)?></h1></div><div class="admin-user">Signed in as <b><?=e($u['name'])?></b></div></header><?=$content?></main></div></body></html><?php exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($a==='business_status'){$status=in_array($_POST['status']??'',['approved','rejected','pending','suspended'],true)?$_POST['status']:'pending';$reason=trim($_POST['reason']??'');$pdo->prepare('UPDATE businesses SET status=?,verified_at=IF(?="approved",NOW(),verified_at),rejection_reason=? WHERE id=?')->execute([$status,$status,$reason?:null,$id]);$q=$pdo->prepare('SELECT owner_id,name FROM businesses WHERE id=?');$q->execute([$id]);$b=$q->fetch();if($b){$message=$status==='approved'?'Your business is approved and visible in the directory.':'Your business status is now '.ucfirst($status).($reason?': '.$reason:'');$pdo->prepare('INSERT INTO notifications(user_id,message)VALUES(?,?)')->execute([$b['owner_id'],$message]);audit($pdo,user()['id'],'Business '.ucfirst($status),$b['name']);}flash('Business status updated.');admin_go('businesses');}
 if($a==='delete_business'){$q=$pdo->prepare('SELECT name FROM businesses WHERE id=?');$q->execute([$id]);$name=$q->fetchColumn();if($name){$pdo->prepare('DELETE FROM businesses WHERE id=?')->execute([$id]);audit($pdo,user()['id'],'Business deleted',(string)$name);}flash('Business deleted.');admin_go('businesses');}
 if($a==='review_status'){$status=$_POST['status']==='visible'?'visible':'hidden';$pdo->prepare('UPDATE reviews SET status=? WHERE id=?')->execute([$status,$id]);audit($pdo,user()['id'],'Review '.$status,'Review #'.$id);flash('Review updated.');admin_go('reviews');}
 if($a==='business_verify'){$verified=(int)($_POST['verified']??0);$q=$pdo->prepare('SELECT owner_id,name,status FROM businesses WHERE id=?');$q->execute([$id]);$b=$q->fetch();if($b&&$b['status']==='approved'){$pdo->prepare('UPDATE businesses SET is_verified=?,verified_at=? WHERE id=?')->execute([$verified,$verified?date('Y-m-d H:i:s'):null,$id]);notify_user($pdo,(int)$b['owner_id'],$verified?'Your business is now verified.':'Business verification was removed.','owner.php','verification');audit($pdo,user()['id'],$verified?'Business verified':'Business unverified',$b['name']);flash('Verification updated.');}admin_go('businesses');}
 if($a==='report_status'){$status=$_POST['status']??'';if(in_array($status,['pending','reviewed','resolved','dismissed'],true)){$q=$pdo->prepare('SELECT user_id FROM business_reports WHERE id=?');$q->execute([$id]);$reporter=(int)$q->fetchColumn();$pdo->prepare('UPDATE business_reports SET status=?,admin_notes=? WHERE id=?')->execute([$status,mb_strimwidth(trim($_POST['notes']??''),0,3000,''),$id]);if($reporter)notify_user($pdo,$reporter,'Your business report is now '.ucfirst($status).'.','notifications.php','report');audit($pdo,user()['id'],'Report '.$status,'Report #'.$id);}admin_go('reports');}
 if($a==='category_add'){$name=trim($_POST['name']??'');if($name){try{$pdo->prepare('INSERT INTO categories(name)VALUES(?)')->execute([$name]);audit($pdo,user()['id'],'Category added',$name);flash('Category added.');}catch(PDOException){flash('That category already exists.','error');}}admin_go('categories');}
 if($a==='category_toggle'){$pdo->prepare('UPDATE categories SET active=NOT active WHERE id=?')->execute([$id]);audit($pdo,user()['id'],'Category status changed','Category #'.$id);flash('Category status updated.');admin_go('categories');}
 if($a==='user_toggle'){$pdo->prepare("UPDATE users SET status=IF(status='active','inactive','active') WHERE id=? AND id<>?")->execute([$id,user()['id']]);audit($pdo,user()['id'],'User status changed','User #'.$id);flash('User status updated.');admin_go('users');}
}
if($view==='dashboard'){$s=$pdo->query("SELECT (SELECT COUNT(*) FROM businesses) businesses,(SELECT COUNT(*) FROM businesses WHERE status='approved') approved,(SELECT COUNT(*) FROM businesses WHERE status='pending') pending,(SELECT COUNT(*) FROM businesses WHERE status='rejected') rejected,(SELECT COUNT(*) FROM users WHERE status='active') users,(SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='owner') owners,(SELECT COUNT(*) FROM reviews) reviews")->fetch();$pending=$pdo->query("SELECT b.*,c.name category,u.name owner FROM businesses b JOIN categories c ON c.id=b.category_id JOIN users u ON u.id=b.owner_id WHERE b.status='pending' ORDER BY b.created_at DESC LIMIT 6")->fetchAll();$logs=$pdo->query('SELECT l.*,u.name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 8')->fetchAll();ob_start();?><section class="admin-grid stats-grid"><?php foreach(['businesses'=>'Total businesses','approved'=>'Verified businesses','pending'=>'Pending review','rejected'=>'Rejected','users'=>'Active users','owners'=>'Business owners','reviews'=>'Total reviews'] as $k=>$label):?><article><b><?=$s[$k]?></b><span><?=$label?></span><small>Live database total</small></article><?php endforeach?></section><section class="panel"><h2>Quick actions</h2><div class="quick-actions"><a href="?view=businesses" class="button dark">Manage businesses</a><a href="?view=pending" class="button coral">Review pending</a><a href="?view=users" class="button light">Manage users</a><a href="?view=categories" class="button light">Manage categories</a></div></section><section class="panel"><h2>Pending verification</h2><?php include __DIR__.'/partials_pending.php'; ?></section><section class="panel"><h2>Recent activity</h2><div class="activity-list"><?php foreach($logs as $log):?><p><b><?=e($log['action'])?></b> — <?=e($log['details'])?><small><?=e($log['name']??'System')?> · <?=e($log['created_at'])?></small></p><?php endforeach;if(!$logs):?><p>No recorded activity yet. Actions performed in this administration panel appear here.</p><?php endif?></div></section><?php admin_head('Dashboard',ob_get_clean());}
if($view==='pending'){$pending=$pdo->query("SELECT b.*,c.name category,u.name owner FROM businesses b JOIN categories c ON c.id=b.category_id JOIN users u ON u.id=b.owner_id WHERE b.status='pending' ORDER BY b.created_at DESC")->fetchAll();ob_start();?><section class="panel"><h2>Listings awaiting verification</h2><?php include __DIR__.'/partials_pending.php'; ?></section><?php admin_head('Pending verification',ob_get_clean());}
if($view==='businesses'){$term=trim($_GET['q']??'');$status=$_GET['status']??'';$where=[];$v=[];if($term){$where[]='(b.name LIKE ? OR u.name LIKE ? OR c.name LIKE ?)';$v=array_fill(0,3,"%$term%");}if(in_array($status,['approved','pending','rejected','suspended'],true)){$where[]='b.status=?';$v[]=$status;}$q=$pdo->prepare('SELECT b.*,c.name category,u.name owner FROM businesses b JOIN categories c ON c.id=b.category_id JOIN users u ON u.id=b.owner_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY b.created_at DESC');$q->execute($v);$rows=$q->fetchAll();ob_start();?><section class="panel"><form class="admin-filter"><input name="q" value="<?=e($term)?>" placeholder="Search business, owner, category"><select name="status"><option value="">All statuses</option><?php foreach(['approved','pending','rejected','suspended'] as $x):?><option <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach?></select><button class="button coral">Search</button></form><div class="table-wrap"><table><tr><th>Business</th><th>Owner</th><th>Location</th><th>Status</th><th>Created</th><th>Actions</th></tr><?php foreach($rows as $b):?><tr><td><b><?=e($b['name'])?></b><small><?=e($b['category'])?></small></td><td><?=e($b['owner'])?></td><td><?=e($b['barangay'])?></td><td><span class="status <?=e($b['status'])?>"><?=e($b['status'])?></span></td><td><?=e(date('M j, Y',strtotime($b['created_at'])))?></td><td><details><summary>Manage</summary><form method="post" class="action-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><select name="status"><option>approved</option><option>pending</option><option>rejected</option><option>suspended</option></select><input name="reason" placeholder="Reason if needed"><button name="action" value="business_status" class="button coral">Save</button><button name="action" value="delete_business" class="danger" onclick="return confirm('Delete this business permanently?')">Delete</button></form></details></td></tr><?php endforeach?></table></div></section><?php admin_head('Business management',ob_get_clean());}
if($view==='users'){$rows=$pdo->query('SELECT u.*,r.name role FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.created_at DESC')->fetchAll();ob_start();?><section class="panel"><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Registered</th><th>Action</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['email'])?></td><td><span class="pill"><?=e($x['role'])?></span></td><td><span class="status <?=e($x['status'])?>"><?=e($x['status'])?></span></td><td><?=e(date('M j, Y',strtotime($x['created_at'])))?></td><td><?php if($x['id']!=user()['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button name="action" value="user_toggle" class="link-button"><?=e($x['status']==='active'?'Deactivate':'Activate')?></button></form><?php endif?></td></tr><?php endforeach?></table></div></section><?php admin_head('Users & owners',ob_get_clean());}
if($view==='categories'){$rows=$pdo->query('SELECT c.*,COUNT(b.id) business_count FROM categories c LEFT JOIN businesses b ON b.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();ob_start();?><section class="panel"><form method="post" class="admin-filter"><input type="hidden" name="csrf" value="<?=csrf()?>"><input required name="name" placeholder="New category name"><button name="action" value="category_add" class="button coral">Add category</button></form><div class="table-wrap"><table><tr><th>Category</th><th>Businesses</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['name'])?></td><td><?=$x['business_count']?></td><td><span class="status <?=$x['active']?'active':'inactive'?>"><?=$x['active']?'active':'inactive'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button name="action" value="category_toggle" class="link-button"><?=$x['active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach?></table></div></section><?php admin_head('Category management',ob_get_clean());}
if($view==='reviews'){$rows=$pdo->query('SELECT r.*,u.name reviewer,b.name business FROM reviews r JOIN users u ON u.id=r.user_id JOIN businesses b ON b.id=r.business_id ORDER BY r.created_at DESC')->fetchAll();ob_start();?><section class="panel"><div class="table-wrap"><table><tr><th>Reviewer</th><th>Business</th><th>Rating</th><th>Review</th><th>Date</th><th>Action</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['reviewer'])?></td><td><?=e($x['business'])?></td><td><?=$x['rating']?>/5</td><td><?=e($x['comment'])?></td><td><?=e(date('M j, Y',strtotime($x['created_at'])))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="status" value="<?=$x['status']==='visible'?'hidden':'visible'?>"><button name="action" value="review_status" class="link-button"><?=$x['status']==='visible'?'Hide':'Restore'?></button></form></td></tr><?php endforeach?></table></div></section><?php admin_head('Review management',ob_get_clean());}
if($view==='logs'){$rows=$pdo->query('SELECT l.*,u.name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 100')->fetchAll();ob_start();?><section class="panel"><div class="activity-list"><?php foreach($rows as $x):?><p><b><?=e($x['action'])?></b> — <?=e($x['details'])?><small><?=e($x['name']??'System')?> · <?=e($x['created_at'])?></small></p><?php endforeach;if(!$rows):?><p>No activity recorded yet.</p><?php endif?></div></section><?php admin_head('Activity logs',ob_get_clean());}
if($view==='reports'){$rows=$pdo->query('SELECT r.*,b.name business,u.name reporter FROM business_reports r JOIN businesses b ON b.id=r.business_id JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC')->fetchAll();ob_start();?><section class="panel"><h2>Business reports</h2><div class="table-wrap"><table><tr><th>Business</th><th>Customer</th><th>Reason</th><th>Details</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['business'])?></td><td><?=e($r['reporter'])?></td><td><?=e(str_replace('_',' ',$r['reason']))?></td><td><?=e($r['details'])?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><form method="post" class="action-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>pending</option><option>reviewed</option><option>resolved</option><option>dismissed</option></select><input name="notes" placeholder="Admin notes"><button name="action" value="report_status" class="button coral">Update</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No reports yet.</td></tr><?php endif?></table></div></section><?php admin_head('Report management',ob_get_clean());}
admin_head('Not found','<section class="panel">This administration page does not exist.</section>');
